def body(secs):
    out=[]
    for h,items in secs:
        out.append('<h2>%s</h2>'%h)
        for it in items:
            if isinstance(it,list):
                out.append('<ul>'+''.join('<li>%s</li>'%x for x in it)+'</ul>')
            else:
                out.append('<p>%s</p>'%it)
    return ''.join(out)
